from pathlib import Path
import json,html,os
T=Path(__file__).resolve().parents[1];B=T/'research/reference-expansion'
rows=[]
for r in json.loads((B/'archive/root-observations.json').read_text())['observations']:
 rows.append(dict(id=r['id'],title=r.get('title'),author=r.get('author'),classification=r['classification'],path=r['path'],url=r['page_url'],note=r['observation']))
for r in json.loads((B/'local-studio-study/output_dir/observations.json').read_text())['observations']:
 rows.append(dict(id=r['id'],title=r.get('title'),author=r.get('author'),classification=r['classification'],path=r['source']['path'],url=r['source']['page_url'],note=str(r['transferable_principle'])+' '+str(r.get('identity_uncertainties') or '')))
e=lambda x:html.escape(str(x or '미확인'),quote=True)
cards=[]
for r in rows:
 p=os.path.relpath(r['path'],B)
 cards.append(f'<article data-class="{e(r["classification"])}" data-search="{e(str(r).lower())}"><a href="{e(p)}"><img loading="lazy" src="{e(p)}" alt="{e(r["id"])} {e(r["title"])}"></a><div><small>{e(r["id"])} · {e(r["classification"])}</small><h2><a href="{e(r["url"])}">{e(r["title"])}</a></h2><p class="credit">{e(r["author"])}</p><p>{e(r["note"])}</p></div></article>')
page='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ducttape Poster — 레퍼런스 연구</title><style>body{margin:0;background:#efede8;color:#1d2224;font:16px/1.6 system-ui,sans-serif}header{padding:40px 5vw;max-width:1200px}h1{font-size:36px;line-height:1.2}header p{max-width:900px}.tools{display:flex;gap:12px;flex-wrap:wrap;padding:0 5vw 24px}input,select{font:inherit;padding:10px;border:1px solid #89918d;background:white}main{display:grid;grid-template-columns:repeat(auto-fill,minmax(275px,1fr));gap:22px;padding:0 5vw 50px}article{background:white;border:1px solid #d9d9d1}article img{display:block;width:100%;height:340px;object-fit:contain;background:#e7e6e1}article>div{padding:18px}h2{font-size:18px;line-height:1.35}small,.credit{color:#525c57;font-size:13px}a{color:inherit}article p{font-size:14px}article[hidden]{display:none}</style><header><h1>매력적인 포스터의 구성 아이디어</h1><p>공식 아카이브의 작품당 한 이미지 200개와 스튜디오 이미지 37개를 실제 관찰한 로컬 연구입니다. 스튜디오 자료는 중복 시리즈·지원 매체·미확인을 구별해 유효 포스터 20그룹으로 집계했습니다. 두 집계 사이의 중복은 확인하지 않았습니다.</p><p>whole-positive는 전체 발상이 유용하다는 뜻이며 품질 인증이 아닙니다. partial-only는 부분 원리, excluded-template는 기본 구성에서 제외할 반례입니다. 작은 글자·프로젝트 대응·크레딧의 한계는 기록에 남겼습니다. 이미지를 누르면 로컬 원본, 제목을 누르면 공식 출처를 엽니다.</p></header><div class="tools"><input id="search" aria-label="검색" placeholder="작품·디자이너·아이디어 검색"><select id="filter" aria-label="분류"><option value="all">모든 관찰</option><option>whole-positive</option><option>partial-only</option><option>excluded-template</option><option>non-poster</option><option>unresolved</option></select><span id="count"></span></div><main>'''+''.join(cards)+'''</main><script>const cards=[...document.querySelectorAll('article')],search=document.querySelector('#search'),filter=document.querySelector('#filter'),count=document.querySelector('#count');function update(){const q=search.value.toLowerCase();let n=0;for(const c of cards){c.hidden=!(c.dataset.search.includes(q)&&(filter.value==='all'||c.dataset.class===filter.value));if(!c.hidden)n++}count.textContent=n+'개 이미지 관찰'}search.addEventListener('input',update);filter.addEventListener('change',update);update();</script></html>'''
with (B/'gallery.html').open('x',encoding='utf-8') as f:f.write(page)
print(json.dumps({'gallery':str(B/'gallery.html'),'cards':len(rows)}))
